const r = await tools.exec_command({cmd:"python - <<'PY'
import json, pathlib, collections, statistics, math
p=pathlib.Path('outputs/metrics.jsonl')
rows=[json.loads(x) for x in p.open()]
print('n',len(rows),'steps',[(r.get('step'),len(r.get('data',{}))) for r in rows[:3]],[(r.get('step'),len(r.get('data',{}))) for r in rows[-3:]])
for r in rows:
 d=r.get('data',{}); s=r.get('step')
 if s in [0,1,2,3,4,5,10,25,50,75,100,125,149,150] or s is None:
  print('\nSTEP',s)
  for k,v in d.items():
   if any(t in k for t in ['reward','score','acc','trunc','length','clip','entropy','kl','loss','grad','lr','time','throughput','seqlen','pg_','adv','ratio','response','turn','valid','mean','max','min','std']):
    if isinstance(v,(int,float,str,bool)):
     print(k, v)
# all keys frequency / type
keys=collections.Counter(k for r in rows for k in r.get('data',{}))
print('\nKEYS',len(keys))
for k,c in keys.most_common(): print(c,k)
PY",workdir:"/user/user1/harbor-runs/206abec8b5ee/workspace",yield_time_ms:10000,max_output_tokens:50000}); text(r.output);

