const r = await tools.exec_command({cmd:"python - <<'PY'
import json, pathlib, collections, re, statistics, math
for fn in ['outputs/rollouts/1.jsonl','outputs/rollouts/75.jsonl','outputs/rollouts/150.jsonl']:
 rows=[json.loads(x) for x in open(fn)]
 print('\n',fn,'rows',len(rows),'step',set(r['step'] for r in rows),'sources',collections.Counter(r['data_source'] for r in rows),'buckets',collections.Counter(r['context_bucket'] for r in rows))
 for k in ['score','acc','oracle_acc']:
  vals=[r[k] for r in rows]; print(k,'mean',sum(vals)/len(vals),'sum',sum(vals),'n',len(vals))
 # group by source, bucket
 for g,rs in [('source math',[r for r in rows if r['data_source']=='math_dapo']),('aime24',[r for r in rows if r['data_source']=='aime24']),('aime25',[r for r in rows if r['data_source']=='aime25'])]:
  if rs: print(g,len(rs),'score',sum(r['score'] for r in rs)/len(rs))
 print('output chars',statistics.mean(len(r['output']) for r in rows),statistics.median(len(r['output']) for r in rows),'max',max(len(r['output']) for r in rows))
 print('answer markers',sum(len(re.findall(r'(?i)answer\\s*:',r['output'])) for r in rows),'boxed',sum('\\boxed' in r['output'] for r in rows))
 for r in rows:
  if r['score']==1:
   print('correct sample',r['problem_id'],repr(r['output'][-160:])); break
PY",workdir:"/user/user1/harbor-runs/206abec8b5ee/workspace",yield_time_ms:10000,max_output_tokens:30000}); text(r.output);

