const r = await tools.exec_command({cmd:"python - <<'PY'
import json,collections,statistics,re, pathlib
for fn in ['outputs/frozen_eval/0.jsonl','outputs/frozen_eval/150.jsonl']:
 rows=[json.loads(x) for x in open(fn)]
 print('\n',fn,'rows',len(rows),'steps',set(r['step'] for r in rows),'sources',collections.Counter(r['data_source'] for r in rows),'buckets',collections.Counter(r['context_bucket'] for r in rows))
 for source in sorted(set(r['data_source'] for r in rows)):
  rs=[r for r in rows if r['data_source']==source]
  print(source,len(rs),'mean score',sum(r['score'] for r in rs)/len(rs),'sum',sum(r['score'] for r in rs),'problem ids',len(set(r['problem_id'] for r in rs)))
 print('overall score',sum(r['score'] for r in rows)/len(rows),'correct',sum(r['score'] for r in rows))
 # unique problem scores
 for pid in list(dict.fromkeys(r['problem_id'] for r in rows)):
  rs=[r for r in rows if r['problem_id']==pid]; print(pid,len(rs),sum(r['score'] for r in rs),rs[0]['gts'])
PY",workdir:"/user/user1/harbor-runs/206abec8b5ee/workspace",yield_time_ms:10000,max_output_tokens:20000}); text(r.output);

