import json,collections,statistics,math,re
from pathlib import Path
for fn in ['outputs/frozen_eval/0.jsonl','outputs/frozen_eval/150.jsonl']:
 rows=[json.loads(x) for x in Path(fn).read_text().splitlines()]
 print('\n',fn)
 for src in ['aime24','aime25']:
  rr=[r for r in rows if r['data_source']==src]
  print(src,'n',len(rr),'scores',sum(r['score'] for r in rr),'mean',sum(r['score'] for r in rr)/len(rr),'unique probs',len(set(r['problem_id'] for r in rr)))
  for b in ['short','long','all']:
   x=[r for r in rr if r['context_bucket']==b]
   if x: print(' ',b,len(x),sum(r['score'] for r in x)/len(x), 'correct',sum(r['score'] for r in x))
  # score by problem ID to compare
  by={r['problem_id']:r['score'] for r in rr}
  print(' per problem',list(by.items())[:5])
# compare exact outputs with same problem across steps
r0={r['problem_id']:r for r in map(json.loads,Path('outputs/frozen_eval/0.jsonl').read_text().splitlines())}
r1={r['problem_id']:r for r in map(json.loads,Path('outputs/frozen_eval/150.jsonl').read_text().splitlines())}
print('\nchanges per problem')
for src in ['aime24','aime25']:
 ids=[k for k,v in r1.items() if v['data_source']==src]
 counts=collections.Counter((r0[k]['score'],r1[k]['score']) for k in ids)
